/**
 * Publishing error taxonomy.
 *
 * Every publishing failure carries a stable `code`. Codes marked actionable are
 * meant to pause a publish operation for user resolution and retry (see
 * DOCS/publishing.md — "Recovery").
 */

export const PUBLISHING_ERROR_CODES = Object.freeze([
  'INVALID_NOTEBOOK',
  'INVALID_MODE',
  'INVALID_DESTINATION',
  'DESTINATION_INSIDE_NOTEBOOK',
  'DESTINATION_NOT_DIRECTORY',
  'DESTINATION_NOT_EMPTY',
  'NOT_A_PUBLICATION',
  'MARKER_MISMATCH',
  'PARENT_REPOSITORY',
  'IGNORED_REQUIRED_FILES',
  'GIT_UNAVAILABLE',
  'GIT_FAILED',
  'GIT_IDENTITY_UNAVAILABLE',
  'REMOTE_CONFLICT',
  'REMOTE_NOT_PUBLICATION',
  'GH_UNAVAILABLE',
  'GH_NOT_AUTHENTICATED',
  'REPOSITORY_EXISTS',
  'REPOSITORY_NOT_FOUND',
  'REPOSITORY_UNAVAILABLE',
  'INVALID_REPOSITORY',
  'INVALID_REPOSITORY_MODE',
  'INVALID_VISIBILITY',
  'INVALID_BRANCH',
  'ORIGIN_MISMATCH',
  'PAGES_SITE_CONFIGURED',
  'PAGES_WORKFLOW_CONFLICT',
  'PAGES_REQUEST_FAILED',
  'WORKFLOW_DISPATCH_FAILED',
  'BUILD_INSTALL_FAILED',
  'PUBLISH_SOURCE_CONFLICT',
  'PUBLISH_IGNORE_INVALID',
  'PUBLISH_BUILD_FAILED',
  'NPM_UNAVAILABLE',
  'OPERATION_NOT_FOUND',
  'OPERATION_NOT_RETRYABLE',
  'UNSUPPORTED_PROVIDER',
  'PROVIDER_NOT_CONNECTED',
  'INVALID_CREDENTIAL',
  'PROJECT_NOT_FOUND',
  'GITHUB_NOT_CONNECTED',
  'GITHUB_REQUEST_FAILED',
  'PUBLISHING_FAILED',
])

/** Error codes that pause an operation for user resolution instead of failing it. */
export const ACTIONABLE_ERROR_CODES = new Set([
  'GIT_UNAVAILABLE',
  'GIT_IDENTITY_UNAVAILABLE',
  'GH_UNAVAILABLE',
  'GH_NOT_AUTHENTICATED',
  'PARENT_REPOSITORY',
  'DESTINATION_NOT_EMPTY',
  'NOT_A_PUBLICATION',
  'MARKER_MISMATCH',
  'REMOTE_CONFLICT',
  'REMOTE_NOT_PUBLICATION',
  'ORIGIN_MISMATCH',
  'PAGES_SITE_CONFIGURED',
  'PAGES_WORKFLOW_CONFLICT',
  'REPOSITORY_EXISTS',
  'REPOSITORY_NOT_FOUND',
  'WORKFLOW_DISPATCH_FAILED',
  'IGNORED_REQUIRED_FILES',
  'BUILD_INSTALL_FAILED',
  'PUBLISH_DEPENDENCY_UNAVAILABLE',
  'PUBLISH_SOURCE_CONFLICT',
  'PUBLISH_IGNORE_INVALID',
])

export function publishingError(code, message, detail = null, hint = null) {
  return Object.assign(new Error(message), {
    code,
    detail,
    hint,
    actionable: ACTIONABLE_ERROR_CODES.has(code),
  })
}
